//#region src/api/users.js
async function listUsers() {
	const res = await apiRequest("/api/v1/users", { validateAuthOnUnauthorized: true });
	return Array.isArray(res?.data) ? res.data : [];
}
async function updateUser(id, user) {
	if (user instanceof FormData) {
		user.append("_method", "PATCH");
		return (await apiRequest(`/api/v1/users/${id}`, {
			method: "POST",
			body: user
		})).data;
	}
	return (await apiRequest(`/api/v1/users/${id}`, {
		method: "PATCH",
		body: user
	})).data;
}
async function deleteUser(id) {
	await apiRequest(`/api/v1/users/${id}`, { method: "DELETE" });
}
async function updateUserPermissions(id, permissions) {
	return (await apiRequest(`/api/v1/users/${id}/permissions`, {
		method: "PATCH",
		body: { permissions }
	})).data;
}
