//#region src/api/notifications.js
async function listNotifications(role, options = {}) {
	const safeRole = encodeURIComponent(role || "");
	return apiRequest(safeRole ? `/api/v1/notifications/${safeRole}` : "/api/v1/notifications", {
		skipAuthRedirect: true,
		...options
	});
}
async function markAsRead(id) {
	return apiRequest(`/api/v1/notifications/${id}/read`, { method: "POST" });
}
async function markAllAsRead() {
	return apiRequest("/api/v1/notifications/read-all", { method: "POST" });
}
