//#region src/api/settings.js
async function getStorageSettings() {
	return (await apiRequest("/api/v1/settings/storage")).data;
}
async function updateStorageSettings(storagePath) {
	return (await apiRequest("/api/v1/settings/storage", {
		method: "PATCH",
		body: { storagePath }
	})).data;
}
async function getStorageLimits() {
	return (await apiRequest("/api/v1/storage-limits")).data;
}
async function updateStorageLimit(userId, limitMb) {
	return (await apiRequest(`/api/v1/storage-limits/${userId}`, {
		method: "PATCH",
		body: { storage_limit_mb: limitMb }
	})).data;
}
async function getCompanyLimits() {
	return (await apiRequest("/api/v1/company-limits/stats")).data || [];
}
async function setCompanyLimit(organization, userLimit) {
	const res = await apiRequest("/api/v1/company-limits", {
		method: "POST",
		body: {
			organization,
			userLimit
		}
	});
	return res.data || res;
}
async function updateCompanyLimit(id, userLimit) {
	const res = await apiRequest(`/api/v1/company-limits/${id}`, {
		method: "PATCH",
		body: { userLimit }
	});
	return res.data || res;
}
