async function listApiKeys() {
	return (await client.get("/integrations/keys")).data;
}
async function storeApiKey(data) {
	return (await client.post("/integrations/keys", data)).data;
}
async function toggleApiKey(id) {
	return (await client.post(`/integrations/keys/${id}/toggle`)).data;
}
async function deleteApiKey(id) {
	return (await client.delete(`/integrations/keys/${id}`)).data;
}
