//#region src/api/support.js
async function getSupportStats() {
	const res = await apiRequest("/api/v1/support/stats");
	return res.data || res;
}
async function getSupportConversations() {
	return (await apiRequest("/api/v1/support/conversations")).data || [];
}
async function createSupportConversation(data) {
	const res = await apiRequest("/api/v1/support/conversations", {
		method: "POST",
		body: data
	});
	return res.data || res;
}
async function getSupportConversation(id) {
	const res = await apiRequest(`/api/v1/support/conversations/${id}`);
	return res.data || res;
}
async function addSupportMessage(conversationId, text) {
	const res = await apiRequest(`/api/v1/support/conversations/${conversationId}/messages`, {
		method: "POST",
		body: { text }
	});
	return res.data || res;
}
async function addParticipant(conversationId, userId) {
	const res = await apiRequest(`/api/v1/support/conversations/${conversationId}/participants`, {
		method: "POST",
		body: { userId }
	});
	return res.data || res;
}
async function updateConversationStatus(conversationId, status) {
	const res = await apiRequest(`/api/v1/support/conversations/${conversationId}/status`, {
		method: "PATCH",
		body: { status }
	});
	return res.data || res;
}
async function getAvailableSupportUsers() {
	return (await apiRequest("/api/v1/support/users")).data || [];
}
//#endregion
