		iconWrap: {
			width: 48,
			height: 48,
			borderRadius: 14,
			background: "#dbeafe",
			display: "flex",
			alignItems: "center",
			justifyContent: "center",
			color: "#2563eb",
			fontSize: 20
		},
		heading: {
			fontSize: 24,
			fontWeight: 700,
			margin: 0,
			color: isDark ? "#f1f5f9" : "#0f172a"
		},
